def parse_duration(s: str) -> int:
    total_seconds = 0
    time_units = {
        's': 1,
        'm': 60,
        'h': 3600
    }

    current_value = ''
    current_unit = None

    for char in s:
        if char.isdigit():
            current_value += char
        elif char in time_units:
            if current_value:
                total_seconds += int(current_value) * time_units[char]
                current_value = ''
            current_unit = char
        else:
            raise ValueError(f"Invalid character: {char}")

    if current_value:
        total_seconds += int(current_value) * time_units.get(current_unit, 1)

    return total_seconds
```

